import{_ as t,a,b as i,c as s,d as o,e as r,f as n}from"./chunks/packing-7.BCH4HY69.js";import{_ as l}from"./chunks/packing-8.BybpqEe_.js";import{_ as h,o as c,c as p,a5 as d}from"./chunks/framework.DGp912Ge.js";const v=JSON.parse('{"title":"Packing","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/operation/packing.md","filePath":"manual/operation/packing.md","lastUpdated":1785806767000}'),g={name:"manual/operation/packing.md"};function u(f,e,b,m,k,_){return c(),p("div",null,[...e[0]||(e[0]=[d('<h1 id="packing" tabindex="-1">Packing <a class="header-anchor" href="#packing" aria-label="Permalink to &quot;Packing&quot;">​</a></h1><p>The RBQ10 is primarily stored and transported using a Pelican case. The model of the Pelican case used is the 1730 Protector Case. Please refer to the images below and store the RBQ10 along with other items accordingly.</p><h2 id="robot-packing-and-unpacking" tabindex="-1">Robot packing and unpacking <a class="header-anchor" href="#robot-packing-and-unpacking" aria-label="Permalink to &quot;Robot packing and unpacking&quot;">​</a></h2><p>The Pelican case has two layers. The lower layer holds the charger, spare rubber feet, and LiDAR; the RBQ10 is placed on top of them.</p><figure><img src="'+t+'" alt="Pelican case lower layer layout"></figure><p>After arranging items in the lower layer, carry the robot as shown in the figure and place it in the case.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>The robot must be carried by two people working together.</p></div></div><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Before transporting the robot, remove any additional equipment attached to it and turn off the power.</p></div></div><figure><img src="'+a+'" alt="Carrying robot into case"></figure><p>After setting the RBQ10 on the floor, extend the legs as shown in the figure.</p><p>Two people should carry the robot, each holding one of the leg areas marked in red.</p><figure><img src="'+i+'" alt="Transport with legs extended"></figure><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Be careful not to let any foreign objects get into the knee joint rotation area, and ensure fingers do not get pinched!</p></div></div><figure><img src="'+s+'" alt="Knee joint caution pose"></figure><p>Place the robot in the Pelican 1730 case to match the case shape.</p><p>After the body is in the case, fold the legs in this order:</p><h3 id="step-1-fold-the-front-legs-knee-joints-fully" tabindex="-1">Step 1: Fold the front legs’ knee joints fully <a class="header-anchor" href="#step-1-fold-the-front-legs-knee-joints-fully" aria-label="Permalink to &quot;Step 1: Fold the front legs’ knee joints fully&quot;">​</a></h3><figure><img src="'+o+'" alt="Front leg knee fold step 1"></figure><h3 id="step-2-rotate-the-front-legs-hip-pitch-joints-and-place-the-legs-into-the-case-recesses" tabindex="-1">Step 2: Rotate the front legs’ hip pitch joints and place the legs into the case recesses <a class="header-anchor" href="#step-2-rotate-the-front-legs-hip-pitch-joints-and-place-the-legs-into-the-case-recesses" aria-label="Permalink to &quot;Step 2: Rotate the front legs’ hip pitch joints and place the legs into the case recesses&quot;">​</a></h3><figure><img src="'+r+'" alt="Front leg hip pitch rotation step 2"></figure><figure><img src="'+n+'" alt="Front leg placed in case step 2 (continued)"></figure><h3 id="step-3-rotate-the-rear-legs-hip-pitch-joints-so-the-legs-go-over-the-front-thighs" tabindex="-1">Step 3: Rotate the rear legs’ hip pitch joints so the legs go over the front thighs <a class="header-anchor" href="#step-3-rotate-the-rear-legs-hip-pitch-joints-so-the-legs-go-over-the-front-thighs" aria-label="Permalink to &quot;Step 3: Rotate the rear legs’ hip pitch joints so the legs go over the front thighs&quot;">​</a></h3><h3 id="step-4-fully-extend-the-rear-shins" tabindex="-1">Step 4: Fully extend the rear shins <a class="header-anchor" href="#step-4-fully-extend-the-rear-shins" aria-label="Permalink to &quot;Step 4: Fully extend the rear shins&quot;">​</a></h3><figure><img src="'+l+'" alt="Rear leg shin extension step 4"></figure><p>Place the remote controller in the side storage next to the robot. Remaining empty space can be used as needed.</p><p>Close the lid to finish packing.</p><p>Unpacking is the reverse of the above steps.</p><h2 id="packing-dimension" tabindex="-1">Packing Dimension <a class="header-anchor" href="#packing-dimension" aria-label="Permalink to &quot;Packing Dimension&quot;">​</a></h2><p><b>Packing Dimension</b></p><table><tr><th>Case Type</th><th>External Dimensions</th><th>Weight (Empty)</th></tr><tr><td>Pelican 1730 Protector Case</td><td> 37.50 x 27.13 x 14.37&quot; (inch)<br> 86.3 x 60.9 x 31.7 (cm) </td><td> 44 lbs / 20 kg </td></tr></table><h2 id="packing-list" tabindex="-1">Packing List <a class="header-anchor" href="#packing-list" aria-label="Permalink to &quot;Packing List&quot;">​</a></h2><p><b>Packing List</b></p><p>The components may vary depending on the optional items.</p><table><tr><th>Category</th><th>Items</th></tr><tr><td>Standard</td><td> RBQ10 x 1 unit<br> Battery charger x 1 unit<br> Spare rubber foot x 4 ea<br> Spare body bumper<br> Remote controller x 1 unit<br> Basic tools (wrench) x 1 set </td></tr><tr><td>Navigation Pack</td><td> Standard list are included<br> LiDAR module x 1 unit </td></tr></table>',34)])])}const q=h(g,[["render",u]]);export{v as __pageData,q as default};
